from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class AstronomyObligation:
    claim_id: str
    title: str
    family: str
    carrier: str
    relation: str
    retained_record: str
    evidence_boundary: str
    statement: str
    falsification_condition: str


