ASTRONOMY_OBLIGATIONS = tuple(row(*item) for item in DATA)


def validate_inventory() -> None:
    if len(ASTRONOMY_OBLIGATIONS) != 72 or len({row.claim_id for row in ASTRONOMY_OBLIGATIONS}) != 72:
        raise ValueError("Astronomy obligation surface must contain 72 unique rows")
    if tuple(dict.fromkeys(row.family for row in ASTRONOMY_OBLIGATIONS)) != FAMILY_ORDER:
        raise ValueError("Astronomy family order changed")


validate_inventory()
OBLIGATIONS = ASTRONOMY_OBLIGATIONS
__all__ = ("AstronomyObligation", "ASTRONOMY_OBLIGATIONS", "OBLIGATIONS", "FAMILY_ORDER", "validate_inventory")
